Here's an example of a multi-threaded implementation of a map with read and write operations and the use of mutexes for synchronization in Java:

```
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class MapExample {

    private final Map<String, Integer> map = new HashMap<>();
    private final Lock lock = new ReentrantLock();

    public void put(String key, int value) {
        lock.lock();
        try {
            map.put(key, value);
        } finally {
            lock.unlock();
        }
    }

    public Integer get(String key) {
        lock.lock();
        try {
            return map.get(key);
        } finally {
            lock.unlock();
        }
    }

}
```

Here's the C++ program to print Pascal's Triangle up to N rows:

```
#include <iostream>
using namespace std;

int main() {
  int n;
  cout << "Enter the number of rows: ";
  cin >> n;

  int arr[n][n];
  // initialize first two rows
  arr[0][0] = 1;
  arr[1][0] = 1;
  arr[1][1] = 1;

  for(int i=2; i<n; i++) {
    arr[i][0] = 1; // set first element to 1
    for(int j=1; j<=i; j++) {
        // calculate each element using the formula
        arr[i][j] = arr[i-1][j-1] + arr[i-1][j];
    }
  }

  // print the triangle
  for(int i=0; i<n; i++) {
    for(int j=0; j<=i; j++) {
        cout << arr[i][j] << " ";
    }
    cout << endl;
  }

  return 0;
}
```

The output will be in the form of Pascal's Triangle up to the desired number of rows.

